#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/mgmt/mcumgr/smp/smp.h>
#include <zephyr/mgmt/mcumgr/mgmt/mgmt.h>
#include <zephyr/mgmt/mcumgr/grp/os_mgmt.h>
#include <string.h>
#include <zcbor_common.h>
#include <zcbor_decode.h>
#include <zcbor_encode.h>
#include "smp_test_util.h"

K_MEM_POOL_DEFINE(test_pool, 64, 64, 1, 4);
#define TEST_POOL_NAME STRINGIFY(test_pool)

extern struct smp_transport smp_dummy_transport;
extern struct net_buf *smp_dummy_tx_pkt;

static struct {
	uint32_t bsize;
	uint32_t nblocks;
	uint32_t nfree;
	uint32_t minfree;
} smp_mpool_data;

static void *os_mgmt_mpstat_setup(void)
{
	smp_dummy_init();
	return NULL;
}

static void os_mgmt_mpstat_teardown(void *dummy)
{
	smp_dummy_deinit();
}

static void test_read_func(void)
{
	struct net_buf *req;
	int rc;
	void *block;
	zcbor_state_t zsd[4];
	struct zcbor_string key;
	bool ok;
	size_t decoded;
	struct zcbor_map_decode_key_val mp_decode[] = {
		ZCBOR_MAP_DECODE_KEY_VAL(bsize, zcbor_uint32_decode, &smp_mpool_data.bsize),
		ZCBOR_MAP_DECODE_KEY_VAL(nblocks, zcbor_uint32_decode, &smp_mpool_data.nblocks),
		ZCBOR_MAP_DECODE_KEY_VAL(nfree, zcbor_uint32_decode, &smp_mpool_data.nfree),
		ZCBOR_MAP_DECODE_KEY_VAL(minfree, zcbor_uint32_decode, &smp_mpool_data.minfree),
	};

	/* To generate some stats */
	block = k_mem_pool_alloc(&test_pool, K_NO_WAIT);
	zassert_not_null(block, "Failed to allocate from test pool");

	req = smp_make_read_req(MGMT_GROUP_ID_OS, OS_MGMT_ID_MPSTAT);
	zassert_not_null(req, "Failed to create request");

	rc = smp_rx_req(req);
	zassert_equal(rc, 0, "smp_rx_req failed");
	zassert_not_null(smp_dummy_tx_pkt, "smp_rx_req did not return a response");

	/* Start decoding the response */
	smp_test_util_strip_header(smp_dummy_tx_pkt);
	zcbor_new_decode_state(zsd, ARRAY_SIZE(zsd), smp_dummy_tx_pkt->data,
			       smp_dummy_tx_pkt->len, 1);

	ok = zcbor_map_start_decode(zsd);
	zassert_true(ok, "Failed to start decoding map");

	ok = zcbor_tstr_decode(zsd, &key);
	zassert_true(ok, "Failed to decode key");
	zassert_equal(key.len, strlen("mempools"), "Incorrect key length");
	zassert_mem_equal(key.value, "mempools", strlen("mempools"), "Incorrect key");

	ok = zcbor_map_start_decode(zsd);
	zassert_true(ok, "Failed to start decoding inner map");

	/* Find our test pool */
	bool found = false;

	do {
		ok = zcbor_tstr_decode(zsd, &key);
		if (ok) {
			if (key.len == strlen(TEST_POOL_NAME) &&
			    memcmp(key.value, TEST_POOL_NAME, strlen(TEST_POOL_NAME)) == 0) {
				found = true;
				break;
			}

			/* Not our pool, skip the map */
			ok = zcbor_map_start_decode(zsd);
			zassert_true(ok, "Failed to start decoding pool map");
			ok = zcbor_skip_bytes(zsd, &decoded);
			zassert_true(ok, "Failed to skip pool map");
			ok = zcbor_map_end_decode(zsd);
			zassert_true(ok, "Failed to end decoding pool map");
		}
	} while (ok);

	zassert_true(found, "Test pool not found in response");

	/* Decode the test pool stats */
	rc = zcbor_map_decode_bulk(zsd, mp_decode, ARRAY_SIZE(mp_decode), &decoded);
	zassert_equal(rc, 0, "Failed to decode pool stats");

	zassert_equal(smp_mpool_data.bsize, 64, "Incorrect bsize");
	zassert_equal(smp_mpool_data.nblocks, 1, "Incorrect nblocks");
	zassert_equal(smp_mpool_data.nfree, 0, "Incorrect nfree");
	zassert_equal(smp_mpool_data.minfree, 0, "Incorrect minfree");

	ok = zcbor_map_end_decode(zsd);
	zassert_true(ok, "Failed to end decoding inner map");

	ok = zcbor_map_end_decode(zsd);
	zassert_true(ok, "Failed to end decoding map");

	/* Cleanup */
	net_buf_unref(smp_dummy_tx_pkt);
	smp_dummy_tx_pkt = NULL;

	k_mem_pool_free(&test_pool, block);
}

ZTEST(os_mgmt_mpstat, test_read)
{
	test_read_func();
}

ZTEST_SUITE(os_mgmt_mpstat, NULL, os_mgmt_mpstat_setup, NULL, NULL, os_mgmt_mpstat_teardown);
